        Itm.Size_Id              Itm_Size_Id                   ,        
        Itm.Lot_Id             , Itm.Ser_Id     , Itm.SDate_Id , Itm.EDate_Id ,
        Itm.Length_Id          , Itm.Width_Id   , Itm.Height_Id,
        Unt.Id      Unit_Id    , Unt.Name    Unit_Name  ,
        Mdl.Id      Model_Id   , Mdl.Name    Model_Name ,
