        Trn.EDate   Trn_EDate  , Trn.Rem     Trn_Rem
   FROM Pur_MPur       Mst ,
        Pur_TPur       Trn ,
        Cpy_Period     Per ,
        Mng_Cont       Cnt ,
        Mng_Curn       Crn ,
        Mng_Curn       BCrn,
        Acc_Acc        Acc ,
        Cpy_Cod_Doc    Doc ,
        Stor_VItem     Itm ,
        Cpy_Cod_Unit   Unt ,
